  `endif

  assign outputSelect = isInstr;
  always @(*) begin
    frgmCounter_willIncrement = 1'b0;
    case(fsm_stateReg)
      fsm_enumDef_72_FORWARD_INSTR : begin
      end
      fsm_enumDef_72_FORWARD_PAGE : begin
        if(io_mergedStrm_fire_1) begin
