            end
          end
        end
      end
      fsm_enumDef_72_FORWARD_PAGE : begin
      end
      default : begin
      end
    endcase
  end

  assign frgmCounter_willOverflowIfInc = (frgmCounter_value == 3'b111);
  assign frgmCounter_willOverflow = (frgmCounter_willOverflowIfInc && frgmCounter_willIncrement);
  always @(*) begin
    frgmCounter_valueNext = (frgmCounter_value + _zz_frgmCounter_valueNext);
    if(frgmCounter_willClear) begin
      frgmCounter_valueNext = 3'b000;
    end
  end

  always @(*) begin
    pageCounter_willIncrement = 1'b0;
    if(frgmCounter_willOverflow) begin
      pageCounter_willIncrement = 1'b1;
    end
  end

  always @(*) begin
    pageCounter_willClear = 1'b0;
    case(fsm_stateReg)
      fsm_enumDef_72_FORWARD_INSTR : begin
        if(io_mergedStrm_valid) begin
          if(when_SysIntf_l56) begin
