      fsm_enumDef_72_FORWARD_PAGE : begin
      end
      default : begin
      end
    endcase
  end

  assign pageCounter_willOverflowIfInc = (pageCounter_value == 32'hffffffff);
  assign pageCounter_willOverflow = (pageCounter_willOverflowIfInc && pageCounter_willIncrement);
  always @(*) begin
    pageCounter_valueNext = (pageCounter_value + _zz_pageCounter_valueNext);
