        fsm_wantStart = 1'b1;
      end
    endcase
  end

  assign fsm_wantKill = 1'b0;
  assign io_mergedStrm_ready = streamDemux_22_io_input_ready;
  assign io_pageStrm_valid = streamDemux_22_io_outputs_0_valid;
  assign io_pageStrm_payload = streamDemux_22_io_outputs_0_payload;
  assign io_instrStrm_valid = streamDemux_22_io_outputs_1_valid;
  assign io_instrStrm_payload = streamDemux_22_io_outputs_1_payload;
  always @(*) begin
    fsm_stateNext = fsm_stateReg;
    case(fsm_stateReg)
      fsm_enumDef_72_FORWARD_INSTR : begin
        if(io_mergedStrm_valid) begin
          if(when_SysIntf_l56) begin
            if(when_SysIntf_l60) begin
              fsm_stateNext = fsm_enumDef_72_FORWARD_PAGE;
