  assign _zz_when_SysIntf_l56_1 = io_mergedStrm_payload[511 : 510];
  assign _zz_when_SysIntf_l56 = _zz_when_SysIntf_l56_1;
  assign when_SysIntf_l56 = (_zz_when_SysIntf_l56 == DedupCoreOp_WRITE2FREE);
  assign _zz_instrPageCount = io_mergedStrm_payload[31 : 0];
  assign io_mergedStrm_fire = (io_mergedStrm_valid && io_mergedStrm_ready);
  assign when_SysIntf_l60 = (io_mergedStrm_fire && (32'h0 < _zz_instrPageCount));
  assign io_mergedStrm_fire_1 = (io_mergedStrm_valid && io_mergedStrm_ready);
