        default : begin
        end
      endcase
      if(io_initEn) begin
        isInstr <= 1'b1;
      end
    end
  end

  always @(posedge clk) begin
    case(fsm_stateReg)
      fsm_enumDef_72_FORWARD_INSTR : begin
