      DedupCoreOp_NOP : io_output_payload_opCode_string = "NOP       ";
      DedupCoreOp_WRITE2FREE : io_output_payload_opCode_string = "WRITE2FREE";
      DedupCoreOp_ERASEREF : io_output_payload_opCode_string = "ERASEREF  ";
      DedupCoreOp_READSSD : io_output_payload_opCode_string = "READSSD   ";
      default : io_output_payload_opCode_string = "??????????";
    endcase
  end
  always @(*) begin
    case(_zz_io_output_payload_opCode)
      DedupCoreOp_NOP : _zz_io_output_payload_opCode_string = "NOP       ";
      DedupCoreOp_WRITE2FREE : _zz_io_output_payload_opCode_string = "WRITE2FREE";
      DedupCoreOp_ERASEREF : _zz_io_output_payload_opCode_string = "ERASEREF  ";
      DedupCoreOp_READSSD : _zz_io_output_payload_opCode_string = "READSSD   ";
      default : _zz_io_output_payload_opCode_string = "??????????";
    endcase
  end
  `endif

  assign maskRouted_0 = (locked ? maskLocked_0 : maskProposal_0);
  assign maskRouted_1 = (locked ? maskLocked_1 : maskProposal_1);
  assign _zz_maskProposal_0 = {io_inputs_1_valid,io_inputs_0_valid};
  assign _zz_maskProposal_0_1 = {_zz_maskProposal_0,_zz_maskProposal_0};
  assign _zz_maskProposal_0_2 = (_zz_maskProposal_0_1 & (~ _zz__zz_maskProposal_0_2));
  assign _zz_maskProposal_0_3 = (_zz_maskProposal_0_2[3 : 2] | _zz_maskProposal_0_2[1 : 0]);
  assign maskProposal_0 = _zz_maskProposal_0_3[0];
  assign maskProposal_1 = _zz_maskProposal_0_3[1];
  assign io_output_fire = (io_output_valid && io_output_ready);
  assign io_output_valid = ((io_inputs_0_valid && maskRouted_0) || (io_inputs_1_valid && maskRouted_1));
  assign _zz_io_output_payload_opCode = (maskRouted_0 ? io_inputs_0_payload_opCode : io_inputs_1_payload_opCode);
  assign io_output_payload_SHA3Hash = (maskRouted_0 ? io_inputs_0_payload_SHA3Hash : io_inputs_1_payload_SHA3Hash);
  assign io_output_payload_tag = (maskRouted_0 ? io_inputs_0_payload_tag : io_inputs_1_payload_tag);
  assign io_output_payload_opCode = _zz_io_output_payload_opCode;
  assign io_output_payload_srcNode = (maskRouted_0 ? io_inputs_0_payload_srcNode : io_inputs_1_payload_srcNode);
  assign io_inputs_0_ready = (maskRouted_0 && io_output_ready);
  assign io_inputs_1_ready = (maskRouted_1 && io_output_ready);
  assign io_chosenOH = {maskRouted_1,maskRouted_0};
  assign _zz_io_chosen = io_chosenOH[1];
  assign io_chosen = _zz_io_chosen;
  always @(posedge clk) begin
    if(!resetn) begin
      locked <= 1'b0;
      maskLocked_0 <= 1'b0;
      maskLocked_1 <= 1'b1;
    end else begin
      if(io_output_valid) begin
        maskLocked_0 <= maskRouted_0;
        maskLocked_1 <= maskRouted_1;
      end
      if(io_output_valid) begin
        locked <= 1'b1;
      end
      if(io_output_fire) begin
        locked <= 1'b0;
      end
    end
  end


